  1→import { useState, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { Card, CardContent } from "@/components/ui/card";
  4→import { Button } from "@/components/ui/button";
  5→import { Badge } from "@/components/ui/badge";
  6→import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
  7→import { User, ShoppingCart, Crown, Zap, ArrowUpRight, AlertTriangle } from "lucide-react";
  8→import { Skeleton } from "@/components/ui/skeleton";
  9→import BuyCreditsDialog from "@/components/BuyCreditsDialog";
 10→import SubscriptionDialog from "@/components/SubscriptionDialog";
 11→import { useNavigate } from "react-router-dom";
 12→
 13→type CreditType = { key: string; color: string; label: string; count: number; desc: string };
 14→
 15→const CREDIT_TYPES: Omit<CreditType, "count">[] = [
 16→  { key: "monthly", color: "hsl(var(--rk-primary))", label: "Monthly", desc: "From your subscription — consumed first." },
 17→  { key: "topup", color: "hsl(var(--rk-score-overall))", label: "Top-up", desc: "One-time pack purchase — never expire, used after monthly." },
 18→  { key: "bonus", color: "hsl(var(--rk-score-education))", label: "Bonus", desc: "Bonus credits — used last, never expire." },
 19→];
 20→
 21→const AccountInfoCard = () => {
 22→  const { user, profile } = useAuth();
 23→  const navigate = useNavigate();
 24→  const [animated, setAnimated] = useState(false);
 25→
 26→  useEffect(() => {
 27→    const t = setTimeout(() => setAnimated(true), 50);
 28→    return () => clearTimeout(t);
 29→  }, []);
 30→
 31→  const subCredits = profile?.subscription_credits ?? 0;
 32→  const topCredits = profile?.topup_credits ?? 0;
 33→  const bonusCredits = profile?.bonus_credits ?? 0;
 34→  const splitTotal = subCredits + topCredits + bonusCredits;
 35→  const legacyCredits = profile?.credits ?? 0;
 36→  const total = splitTotal > 0 ? splitTotal : legacyCredits;
 37→  const showLegacy = splitTotal === 0 && legacyCredits > 0;
 38→
 39→  const plan = profile?.plan ?? "free";
 40→  const isPaid = plan !== "free";
 41→  const isLow = total < 3;
 42→
 43→  // Build credit types with counts
 44→  const creditTypes: CreditType[] = showLegacy
 45→    ? [{ key: "legacy", color: "hsl(var(--rk-primary))", label: "Available", count: legacyCredits, desc: "Your available credits." }]
 46→    : CREDIT_TYPES.map((t) => ({
 47→        ...t,
 48→        count: t.key === "monthly" ? subCredits : t.key === "topup" ? topCredits : bonusCredits,
 49→      }));
 50→
 51→  const activeSegments = creditTypes.filter((t) => t.count > 0);
 52→  const activeSource = subCredits > 0 ? "monthly" : topCredits > 0 ? "top-up" : bonusCredits > 0 ? "bonus" : null;
 53→
 54→
 55→  return (
 56→    <Card className="overflow-hidden">
 57→      {/* Hero banner */}
 58→      <div className="relative bg-gradient-to-br from-primary/10 via-primary/5 to-transparent dark:from-primary/20 dark:via-primary/10 px-6 pt-6 pb-8">
 59→        <div className="flex items-start justify-between">
 60→          <div className="flex items-center gap-3">
 61→            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/15 ring-2 ring-primary/20">
 62→              <User className="h-6 w-6 text-primary" />
 63→            </div>
 64→            <div>
 65→              <p className="text-sm font-medium text-muted-foreground">Welcome back</p>
 66→              <p className="text-base font-semibold text-foreground truncate max-w-[220px] sm:max-w-none">
 67→                {user?.email}
 68→              </p>
 69→            </div>
 70→          </div>
 71→          <div className="flex items-center gap-2">
 72→            <Badge variant={isPaid ? "default" : "secondary"} className="gap-1.5 capitalize">
 73→              {isPaid ? <Crown className="h-3 w-3" /> : <Zap className="h-3 w-3" />}
 74→              {isPaid ? plan : "Pay As You Go"}
 75→            </Badge>
 76→            <SubscriptionDialog
 77→              trigger={
 78→                <Button variant="ghost" size="sm" className="h-7 gap-1 text-xs text-primary hover:text-primary">
 79→                  <ArrowUpRight className="h-3 w-3" />
 80→                  {isPaid ? "Manage" : "Upgrade"}
 81→                </Button>
 82→              }
 83→            />
 84→          </div>
 85→        </div>
 86→      </div>
 87→
 88→      {/* Credits section */}
 89→      <CardContent className="px-6 py-5 space-y-3">
 90→        {!profile ? (
 91→          <div className="space-y-3">
 92→            <div className="flex items-center justify-between">
 93→              <Skeleton className="h-4 w-16" />
 94→              <Skeleton className="h-7 w-24" />
 95→            </div>
 96→            <Skeleton className="h-2 w-full rounded-full" />
 97→            <div className="flex gap-4">
 98→              <Skeleton className="h-3 w-20" />
 99→              <Skeleton className="h-3 w-20" />
100→              <Skeleton className="h-3 w-20" />
101→            </div>
102→          </div>
103→        ) : (
104→        <>
105→        {/* Header row */}
106→        <div className="flex items-center justify-between">
107→          <span className="text-sm font-semibold text-foreground">Credits</span>
108→          <div className="flex items-center gap-3">
109→            <span className="text-sm font-semibold text-foreground tabular-nums">
110→              {total}
111→              <span className="text-muted-foreground font-normal ml-1">left</span>
112→            </span>
113→            <BuyCreditsDialog
114→              trigger={
115→                <Button size="sm" variant="outline" className="h-7 gap-1.5 text-xs">
116→                  <ShoppingCart className="h-3 w-3" />
117→                  Buy
118→                </Button>
119→              }
120→            />
121→          </div>
122→        </div>
123→
124→        {/* Segmented bar */}
125→        <TooltipProvider delayDuration={80}>
126→          <div className="space-y-2">
127→            {/* Bar track */}
128→            <div className="relative h-2 w-full rounded-full bg-muted">
129→              <div className="absolute inset-0 flex gap-[2px]">
130→                {activeSegments.map((seg, i) => {
131→                  const pct = (seg.count / total) * 100;
132→                  return (
133→                    <Tooltip key={seg.key}>
134→                      <TooltipTrigger asChild>
135→                        <div
136→                          className="h-full cursor-pointer transition-all duration-500 ease-out hover:brightness-110"
137→                          style={{
138→                            width: animated ? `${pct}%` : "0%",
139→                            backgroundColor: seg.color,
140→                            transitionDelay: `${i * 100}ms`,
141→                            borderRadius:
142→                              activeSegments.length === 1
143→                                ? "9999px"
144→                                : i === 0
145→                                ? "9999px 0 0 9999px"
146→                                : i === activeSegments.length - 1
147→                                ? "0 9999px 9999px 0"
148→                                : "0",
149→                          }}
150→                        />
151→                      </TooltipTrigger>
152→                      <TooltipContent side="top" className="max-w-[220px] p-3 space-y-1">
153→                        <div className="flex items-center gap-2">
154→                          <span className="inline-block w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: seg.color }} />
155→                          <span className="font-semibold text-sm">{seg.label}</span>
156→                        </div>
157→                        <p className="text-base font-bold tabular-nums">{seg.count} credits</p>
158→                        <p className="text-xs text-muted-foreground leading-relaxed">{seg.desc}</p>
159→                      </TooltipContent>
160→                    </Tooltip>
161→                  );
162→                })}
163→              </div>
164→            </div>
165→
166→            {/* Always-visible legend */}
167→            <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
168→              {creditTypes.map((ct) => (
169→                <span
170→                  key={ct.key}
171→                  className={`flex items-center gap-1.5 text-xs ${ct.count > 0 ? "text-muted-foreground" : "text-muted-foreground/40"}`}
172→                >
173→                  <span
174→                    className="inline-block w-2 h-2 rounded-full shrink-0"
175→                    style={{ backgroundColor: ct.color, opacity: ct.count > 0 ? 1 : 0.3 }}
176→                  />
177→                  {ct.label} ({ct.count})
178→                </span>
179→              ))}
180→              {total === 0 && (
181→                <span className="flex items-center gap-1.5 text-xs text-destructive">
182→                  <AlertTriangle className="h-3 w-3" />
183→                  No credits remaining
184→                </span>
185→              )}
186→            </div>
187→
188→            {/* Active source note */}
189→            {activeSource && !showLegacy && (
190→              <p className="text-[11px] text-muted-foreground">
191→                Using {activeSource} credits first.{" "}
192→                {activeSource === "monthly" && "Top-up & bonus credits never expire."}
193→              </p>
194→            )}
195→          </div>
196→        </TooltipProvider>
197→
198→        {isLow && total > 0 && (
199→          <div className="rounded-md bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive flex items-center gap-1.5">
200→            <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
201→            Low credits — top up to keep ranking resumes.
202→          </div>
203→        )}
204→        {total === 0 && (
205→          <div className="rounded-md bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive flex items-center gap-1.5">
206→            <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
207→            No credits left — buy a pack or upgrade to continue ranking.
208→          </div>
209→        )}
210→        </>
211→        )}
212→      </CardContent>
213→    </Card>
214→  );
215→};
216→
217→export default AccountInfoCard;
218→

  1→import { useState } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { Card, CardContent } from "@/components/ui/card";
  5→import { Button } from "@/components/ui/button";
  6→import { Input } from "@/components/ui/input";
  7→import { Switch } from "@/components/ui/switch";
  8→import { Label } from "@/components/ui/label";
  9→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
 10→import { toast } from "sonner";
 11→import { Copy, Mail, Check, ChevronDown, Info, RefreshCw, Loader2 } from "lucide-react";
 12→
 13→const EmailInboxCard = () => {
 14→  const { user, profile, refreshProfile } = useAuth();
 15→  const [togglingEmail, setTogglingEmail] = useState(false);
 16→  const [copied, setCopied] = useState(false);
 17→  const [howItWorksOpen, setHowItWorksOpen] = useState(false);
 18→  const [regenerating, setRegenerating] = useState(false);
 19→
 20→  const handleCopyInbox = () => {
 21→    if (profile?.inbox_email) {
 22→      navigator.clipboard.writeText(profile.inbox_email);
 23→      setCopied(true);
 24→      toast.success("Inbox email copied to clipboard.");
 25→      setTimeout(() => setCopied(false), 2000);
 26→    }
 27→  };
 28→
 29→  const handleRegenerateInbox = async () => {
 30→    if (!user) return;
 31→    setRegenerating(true);
 32→    try {
 33→      const { data, error } = await supabase.rpc("generate_user_inbox_email", { p_user_id: user.id });
 34→      if (error) throw error;
 35→      await refreshProfile();
 36→      toast.success(`Inbox regenerated: ${data}`);
 37→    } catch (e: any) {
 38→      toast.error(e.message || "Failed to regenerate inbox");
 39→    } finally {
 40→      setRegenerating(false);
 41→    }
 42→  };
 43→
 44→  const handleToggleEmail = async (checked: boolean) => {
 45→    if (!user) return;
 46→    setTogglingEmail(true);
 47→    const { error } = await supabase
 48→      .from("profiles")
 49→      .update({ email_enabled: checked })
 50→      .eq("user_id", user.id);
 51→    if (error) {
 52→      toast.error(error.message);
 53→    } else {
 54→      await refreshProfile();
 55→      toast.success(checked ? "Email enabled" : "Email disabled");
 56→    }
 57→    setTogglingEmail(false);
 58→  };
 59→
 60→  return (
 61→    <Card className="overflow-hidden">
 62→      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
 63→        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
 64→          <Mail className="h-4.5 w-4.5 text-primary" />
 65→        </div>
 66→        <div>
 67→          <h3 className="text-base font-semibold text-foreground">Email Inbox</h3>
 68→          <p className="text-xs text-muted-foreground">
 69→            Forward resumes here to auto-add them to your jobs.
 70→          </p>
 71→        </div>
 72→      </div>
 73→      <CardContent className="px-6 pt-3 pb-5 space-y-4">
 74→        {profile?.inbox_email ? (
 75→          <>
 76→            <div>
 77→              <Label className="text-xs text-muted-foreground mb-1.5 block">Your fallback inbox</Label>
 78→              <div className="flex items-center gap-2">
 79→                <Input
 80→                  value={profile.inbox_email}
 81→                  readOnly
 82→                  className="font-mono text-sm bg-accent/50"
 83→                />
 84→                <Button
 85→                  variant="outline"
 86→                  size="icon"
 87→                  onClick={handleCopyInbox}
 88→                  title="Copy"
 89→                  className="shrink-0"
 90→                >
 91→                  {copied ? (
 92→                    <Check className="h-4 w-4 text-primary" />
 93→                  ) : (
 94→                    <Copy className="h-4 w-4" />
 95→                  )}
 96→                </Button>
 97→                <Button
 98→                  variant="outline"
 99→                  size="icon"
100→                  onClick={handleRegenerateInbox}
101→                  title="Regenerate inbox email"
102→                  className="shrink-0"
103→                  disabled={regenerating}
104→                >
105→                  {regenerating ? (
106→                    <Loader2 className="h-4 w-4 animate-spin" />
107→                  ) : (
108→                    <RefreshCw className="h-4 w-4" />
109→                  )}
110→                </Button>
111→              </div>
112→            </div>
113→            <p className="text-xs text-muted-foreground">
114→              Each job also gets its own unique inbox email. Check the job detail page to copy it.
115→            </p>
116→          </>
117→        ) : (
118→          <div className="rounded-md bg-accent/50 px-3 py-3 text-sm text-muted-foreground text-center">
119→            No inbox email assigned yet.
120→          </div>
121→        )}
122→        <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
123→          <Label htmlFor="email-toggle" className="text-sm font-medium cursor-pointer">
124→            Email ingestion enabled
125→          </Label>
126→          <Switch
127→            id="email-toggle"
128→            checked={profile?.email_enabled ?? true}
129→            onCheckedChange={handleToggleEmail}
130→            disabled={togglingEmail}
131→          />
132→        </div>
133→
134→        {/* How it works */}
135→        <Collapsible open={howItWorksOpen} onOpenChange={setHowItWorksOpen}>
136→          <CollapsibleTrigger asChild>
137→            <Button variant="ghost" size="sm" className="w-full justify-between text-muted-foreground text-xs">
138→              <span className="flex items-center gap-1.5">
139→                <Info className="h-3.5 w-3.5" />
140→                How email ingestion works
141→              </span>
142→              <ChevronDown className={`h-3.5 w-3.5 transition-transform ${howItWorksOpen ? "rotate-180" : ""}`} />
143→            </Button>
144→          </CollapsibleTrigger>
145→          <CollapsibleContent className="pt-2">
146→            <div className="rounded-md bg-muted/50 p-3 text-xs text-muted-foreground space-y-2.5">
147→              <p><strong>Per-job inbox:</strong> Each job gets a unique email address (e.g. <code className="bg-muted px-1 py-0.5 rounded text-[11px]">you+j-abc123@inbound.rankora.co</code>). Forward resumes to it and they'll be attached directly to that job.</p>
148→              <p><strong>Fallback inbox:</strong> Your personal inbox above routes resumes to your most recent pending job. Use this when you don't need job-specific routing.</p>
149→              <p><strong>Routing priority:</strong> Job-specific inbox is checked first. If no match, the fallback inbox routes to your latest pending job. If no pending job exists, one is auto-created.</p>
150→              <p><strong>Supported formats:</strong> PDF and DOCX attachments only. Max 20 attachments per email.</p>
151→            </div>
152→          </CollapsibleContent>
153→        </Collapsible>
154→      </CardContent>
155→    </Card>
156→  );
157→};
158→
159→export default EmailInboxCard;
160→

  1→import { useState } from "react";
  2→import { supabase } from "@/integrations/supabase/client";
  3→import { Card, CardContent } from "@/components/ui/card";
  4→import { Button } from "@/components/ui/button";
  5→import { Input } from "@/components/ui/input";
  6→import { Label } from "@/components/ui/label";
  7→import { toast } from "sonner";
  8→import { Shield, Eye, EyeOff } from "lucide-react";
  9→
 10→const ChangePasswordCard = () => {
 11→  const [newPassword, setNewPassword] = useState("");
 12→  const [confirmPassword, setConfirmPassword] = useState("");
 13→  const [saving, setSaving] = useState(false);
 14→  const [showPassword, setShowPassword] = useState(false);
 15→
 16→  const handleChangePassword = async () => {
 17→    if (newPassword.length < 6) {
 18→      toast.error("Password too short — must be at least 6 characters.");
 19→      return;
 20→    }
 21→    if (newPassword !== confirmPassword) {
 22→      toast.error("Passwords don't match");
 23→      return;
 24→    }
 25→    setSaving(true);
 26→    const { error } = await supabase.auth.updateUser({ password: newPassword });
 27→    if (error) {
 28→      toast.error(error.message);
 29→    } else {
 30→      toast.success("Password updated");
 31→      setNewPassword("");
 32→      setConfirmPassword("");
 33→    }
 34→    setSaving(false);
 35→  };
 36→
 37→  const passwordsMatch = newPassword && confirmPassword && newPassword === confirmPassword;
 38→  const passwordsMismatch = confirmPassword && newPassword !== confirmPassword;
 39→
 40→  return (
 41→    <Card className="overflow-hidden">
 42→      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
 43→        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
 44→          <Shield className="h-4.5 w-4.5 text-primary" />
 45→        </div>
 46→        <div>
 47→          <h3 className="text-base font-semibold text-foreground">Change Password</h3>
 48→          <p className="text-xs text-muted-foreground">Update your account password.</p>
 49→        </div>
 50→      </div>
 51→      <CardContent className="px-6 pt-3 pb-5 space-y-4">
 52→        <div className="space-y-2">
 53→          <Label htmlFor="new-password" className="text-sm">New password</Label>
 54→          <div className="relative">
 55→            <Input
 56→              id="new-password"
 57→              type={showPassword ? "text" : "password"}
 58→              placeholder="Min 6 characters"
 59→              value={newPassword}
 60→              onChange={(e) => setNewPassword(e.target.value)}
 61→              className="pr-10"
 62→            />
 63→            <button
 64→              type="button"
 65→              onClick={() => setShowPassword(!showPassword)}
 66→              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
 67→            >
 68→              {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
 69→            </button>
 70→          </div>
 71→        </div>
 72→        <div className="space-y-2">
 73→          <Label htmlFor="confirm-password" className="text-sm">Confirm password</Label>
 74→          <Input
 75→            id="confirm-password"
 76→            type={showPassword ? "text" : "password"}
 77→            placeholder="Re-enter password"
 78→            value={confirmPassword}
 79→            onChange={(e) => setConfirmPassword(e.target.value)}
 80→            className={passwordsMismatch ? "border-destructive focus-visible:ring-destructive" : passwordsMatch ? "border-primary/50 focus-visible:ring-primary" : ""}
 81→          />
 82→          {passwordsMismatch && (
 83→            <p className="text-xs text-destructive">Passwords don't match.</p>
 84→          )}
 85→          {passwordsMatch && (
 86→            <p className="text-xs text-primary">Passwords match ✓</p>
 87→          )}
 88→        </div>
 89→        <Button
 90→          onClick={handleChangePassword}
 91→          disabled={saving || !newPassword || !passwordsMatch}
 92→          className="w-full"
 93→        >
 94→          {saving ? "Updating…" : "Update password"}
 95→        </Button>
 96→      </CardContent>
 97→    </Card>
 98→  );
 99→};
100→
101→export default ChangePasswordCard;
102→

  1→import { useState, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { Card, CardContent } from "@/components/ui/card";
  5→import { Button } from "@/components/ui/button";
  6→import { Badge } from "@/components/ui/badge";
  7→import { Skeleton } from "@/components/ui/skeleton";
  8→import { Coins, History, Zap } from "lucide-react";
  9→
 10→interface UsageLog {
 11→  id: string;
 12→  created_at: string;
 13→  credits_used: number;
 14→  job_id: string | null;
 15→  job_title?: string | null;
 16→}
 17→
 18→const PAGE_SIZE = 10;
 19→
 20→const UsageHistoryCard = () => {
 21→  const { user } = useAuth();
 22→  const [usageLogs, setUsageLogs] = useState<UsageLog[]>([]);
 23→  const [loading, setLoading] = useState(true);
 24→  const [page, setPage] = useState(0);
 25→  const [hasMore, setHasMore] = useState(false);
 26→  const [loadingMore, setLoadingMore] = useState(false);
 27→
 28→  const fetchLogs = async (pageNum: number, append = false) => {
 29→    if (!user) return;
 30→    if (pageNum === 0) setLoading(true);
 31→    else setLoadingMore(true);
 32→
 33→    const { data } = await supabase
 34→      .from("usage_logs")
 35→      .select("id, created_at, credits_used, job_id")
 36→      .eq("user_id", user.id)
 37→      .order("created_at", { ascending: false })
 38→      .range(pageNum * PAGE_SIZE, (pageNum + 1) * PAGE_SIZE - 1);
 39→
 40→    if (data) {
 41→      setHasMore(data.length === PAGE_SIZE);
 42→      const jobIds = [...new Set(data.map(l => l.job_id).filter(Boolean))] as string[];
 43→      let jobTitles: Record<string, string | null> = {};
 44→      if (jobIds.length > 0) {
 45→        const { data: jobs } = await supabase.from("jobs").select("id, title").in("id", jobIds);
 46→        if (jobs) jobs.forEach(j => { jobTitles[j.id] = j.title; });
 47→      }
 48→      const mapped = data.map(l => ({
 49→        ...l,
 50→        job_title: l.job_id ? (jobTitles[l.job_id] ?? "Untitled Job") : null,
 51→      }));
 52→      setUsageLogs(prev => append ? [...prev, ...mapped] : mapped);
 53→    }
 54→    setLoading(false);
 55→    setLoadingMore(false);
 56→  };
 57→
 58→  useEffect(() => {
 59→    fetchLogs(0);
 60→  }, [user]);
 61→
 62→  const loadMore = () => {
 63→    const nextPage = page + 1;
 64→    setPage(nextPage);
 65→    fetchLogs(nextPage, true);
 66→  };
 67→
 68→  return (
 69→    <Card className="overflow-hidden">
 70→      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
 71→        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
