114→      const { data, error } = await (supabase as any)
115→        .from("feature_request_votes")
116→        .select("feature_request_id")
117→        .eq("user_id", user!.id);
118→      if (error) throw error;
119→      return (data as { feature_request_id: string }[]).map((v) => v.feature_request_id);
120→    },
121→  });
122→
123→  // ── Derived data ──
124→
125→  const statusCounts = requests.reduce<Record<string, number>>((acc, r) => {
126→    acc[r.status] = (acc[r.status] || 0) + 1;
127→    return acc;
128→  }, {});
129→
130→  const filtered = requests
131→    .filter((r) => statusFilter === "all" || r.status === statusFilter)
132→    .sort((a, b) => {
133→      if (sortBy === "most_voted") return b.votes - a.votes;
134→      return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
135→    });
136→
137→  const selected = requests.find((r) => r.id === selectedId) || null;
138→  const hasVoted = (id: string) => myVotes.includes(id);
139→
140→  const plannedCount = (statusCounts.planned || 0) + (statusCounts.in_progress || 0);
141→  const shippedCount = statusCounts.done || 0;
142→
143→  // ── Actions ──
144→
145→  const handleSubmit = async (e: React.FormEvent) => {
146→    e.preventDefault();
147→    if (!title.trim()) { toast.error("Please enter a title"); return; }
148→    if (!description.trim()) { toast.error("Please describe your idea"); return; }
149→    if (!user) { toast.error("Please sign in to submit"); return; }
150→
151→    setSubmitting(true);
152→    try {
153→      const { error } = await (supabase as any).from("feature_requests").insert({
154→        user_id: user.id,
155→        title: title.trim(),
156→        description: description.trim(),
157→        category,
158→      });
159→      if (error) throw error;
160→      setTitle("");
161→      setDescription("");
162→      setCategory("Feature");
163→      toast.success("Feature request submitted!");
164→      qc.invalidateQueries({ queryKey: ["feature_requests"] });
165→    } catch (err: any) {
166→      toast.error(err.message || "Failed to submit");
167→    } finally {
168→      setSubmitting(false);
169→    }
170→  };
171→
172→  const handleVote = async (requestId: string) => {
173→    if (!user) { toast.error("Please sign in to vote"); return; }
174→    try {
175→      const { data, error } = await supabase.rpc("toggle_feature_vote", { p_request_id: requestId });
176→      if (error) throw error;
177→      qc.invalidateQueries({ queryKey: ["feature_requests"] });
178→      qc.invalidateQueries({ queryKey: ["my_feature_votes"] });
179→    } catch (err: any) {
180→      toast.error(err.message || "Vote failed");
181→    }
182→  };
183→
184→  const handleShare = (r: FeatureRequest) => {
185→    const url = `${window.location.origin}/request-feature?id=${r.id}`;
186→    navigator.clipboard.writeText(url);
187→    toast.success("Link copied to clipboard");
188→  };
189→
190→  // ── Render ──
191→
192→  return (
193→    <SidebarLayout>
194→      <main className="mx-auto max-w-3xl px-4 py-10 space-y-8">
195→        {/* Hero */}
196→        <div className="space-y-3">
197→          <p className="text-xs font-semibold uppercase tracking-widest text-primary">Feature Requests</p>
198→          <h1 className="text-3xl font-bold tracking-tight">What should we build next?</h1>
199→          <p className="text-muted-foreground">
200→            Upvote features you want, or suggest something new. We review every request and ship based on community votes.
201→          </p>
202→          <div className="flex items-center gap-3 pt-1">
203→            <Badge variant="outline" className="text-xs font-medium gap-1.5">
204→              <span className="font-bold">{requests.length}</span> total requests
205→            </Badge>
206→            <Badge variant="outline" className="text-xs font-medium gap-1.5">
207→              <span className="font-bold">{plannedCount}</span> planned
208→            </Badge>
209→            <Badge variant="outline" className="text-xs font-medium gap-1.5">
210→              <span className="font-bold">{shippedCount}</span> shipped
211→            </Badge>
212→          </div>
213→        </div>
214→
215→        {/* Submit Form */}
216→        <Card className="border">
217→          <CardContent className="pt-6">
218→            <div className="flex items-center gap-3 mb-5">
219→              <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
220→                <Plus className="h-4 w-4 text-primary" />
221→              </div>
222→              <div>
223→                <p className="font-semibold text-sm">Suggest a feature</p>
224→                <p className="text-xs text-muted-foreground">Your idea could be in our next release</p>
225→              </div>
226→            </div>
227→            <Separator className="mb-5" />
228→            <form onSubmit={handleSubmit} className="space-y-4">
229→              <div className="space-y-1.5">
230→                <Label className="text-sm font-medium">Title</Label>
231→                <Input
232→                  placeholder="Short title, e.g. Export results to CSV"
233→                  value={title}
234→                  onChange={(e) => setTitle(e.target.value)}
235→                  maxLength={100}
236→                />
237→              </div>
238→              <div className="space-y-1.5">
239→                <Label className="text-sm font-medium">Description</Label>
240→                <Textarea
241→                  placeholder="Describe what it does and why it would be useful..."
242→                  value={description}
243→                  onChange={(e) => setDescription(e.target.value)}
244→                  maxLength={2000}
245→                  className="min-h-[100px]"
246→                />
247→              </div>
248→              <div className="flex items-end gap-3">
249→                <div className="flex-1 space-y-1.5">
250→                  <Label className="text-sm font-medium">Category</Label>
251→                  <Select value={category} onValueChange={setCategory}>
252→                    <SelectTrigger><SelectValue /></SelectTrigger>
253→                    <SelectContent>
254→                      {CATEGORIES.map((c) => (
255→                        <SelectItem key={c} value={c}>{c}</SelectItem>
256→                      ))}
257→                    </SelectContent>
258→                  </Select>
259→                </div>
260→                <Button type="submit" disabled={submitting || !user} className="gap-2">
261→                  {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
262→                  Submit request
263→                </Button>
264→              </div>
265→              {!user && (
266→                <p className="text-xs text-muted-foreground">Sign in to submit a feature request.</p>
267→              )}
268→            </form>
269→          </CardContent>
270→        </Card>
271→
272→        {/* Filters + Sort */}
273→        <div className="flex items-center justify-between gap-4 flex-wrap">
274→          <div className="flex items-center gap-2 flex-wrap">
275→            {STATUS_TABS.map((tab) => {
276→              const count = tab.value === "all" ? requests.length : (statusCounts[tab.value] || 0);
277→              const active = statusFilter === tab.value;
278→              return (
279→                <button
280→                  key={tab.value}
281→                  onClick={() => setStatusFilter(tab.value)}
282→                  className={`inline-flex items-center gap-1.5 text-xs font-medium px-3 py-1.5 rounded-full border transition-colors ${
283→                    active
284→                      ? "bg-foreground text-background border-foreground"
285→                      : "bg-background text-muted-foreground border-border hover:border-foreground/30"
286→                  }`}
287→                >
288→                  {tab.label}
289→                  <span className={`text-[11px] tabular-nums ${active ? "text-background/70" : "text-muted-foreground/60"}`}>
290→                    {count}
291→                  </span>
292→                </button>
293→              );
294→            })}
295→          </div>
296→          <Select value={sortBy} onValueChange={setSortBy}>
297→            <SelectTrigger className="w-[140px] h-8 text-xs">
298→              <SelectValue />
299→            </SelectTrigger>
300→            <SelectContent>
301→              <SelectItem value="most_voted">Most voted</SelectItem>
302→              <SelectItem value="newest">Newest</SelectItem>
303→            </SelectContent>
304→          </Select>
305→        </div>
306→
307→        {/* Request List */}
308→        <div className="space-y-3">
309→          {isLoading ? (
310→            <div className="flex items-center justify-center py-16">
311→              <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
312→            </div>
313→          ) : filtered.length === 0 ? (
314→            <Card>
315→              <CardContent className="py-12 text-center text-muted-foreground text-sm">
316→                {statusFilter === "all"
317→                  ? "No feature requests yet. Be the first to suggest one!"
318→                  : "No requests with this status."}
319→              </CardContent>
320→            </Card>
321→          ) : (
322→            filtered.map((r) => (
323→              <Card key={r.id} className="border hover:border-border/80 transition-colors">
324→                <CardContent className="p-4 flex gap-4">
325→                  {/* Vote Button */}
326→                  <button
327→                    onClick={() => handleVote(r.id)}
328→                    className={`flex flex-col items-center justify-center gap-0.5 w-14 shrink-0 rounded-lg border py-2 transition-colors ${
329→                      hasVoted(r.id)
330→                        ? "bg-primary/10 border-primary/30 text-primary"
331→                        : "bg-background border-border text-muted-foreground hover:border-foreground/30"
332→                    }`}
333→                  >
334→                    <ChevronUp className="h-4 w-4" />
335→                    <span className="text-sm font-bold tabular-nums">{r.votes}</span>
336→                    <span className="text-[11px]">vote</span>
337→                  </button>
338→
339→                  {/* Content */}
340→                  <div className="flex-1 min-w-0">
341→                    <div className="flex items-start justify-between gap-3">
342→                      <h3 className="font-semibold text-sm leading-snug">{r.title}</h3>
343→                      <StatusBadge status={r.status} />
344→                    </div>
345→                    <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{r.description}</p>
346→                    <div className="flex items-center justify-between mt-3">
347→                      <div className="flex items-center gap-2">
348→                        <Badge variant="secondary" className="text-[11px] font-normal px-2 py-0">{r.category}</Badge>
349→                        <span className="text-[11px] text-muted-foreground">
350→                          {new Date(r.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
351→                        </span>
352→                      </div>
353→                      <button
354→                        onClick={() => setSelectedId(r.id)}
355→                        className="text-[11px] text-muted-foreground hover:text-foreground transition-colors flex items-center gap-1"
356→                      >
357→                        View details <ArrowRight className="h-3 w-3" />
358→                      </button>
359→                    </div>
360→                  </div>
361→                </CardContent>
362→              </Card>
363→            ))
364→          )}
365→        </div>
366→      </main>
367→
368→      {/* Detail Side Panel */}
369→      <Sheet open={!!selected} onOpenChange={(o) => !o && setSelectedId(null)}>
370→        <SheetContent className="sm:max-w-lg w-full overflow-y-auto">
371→          {selected && (
372→            <>
373→              <SheetHeader className="space-y-3 pb-4">
374→                <div className="flex items-center gap-2 flex-wrap">
375→                  <StatusBadge status={selected.status} />
376→                  <Badge variant="secondary" className="text-xs">{selected.category}</Badge>
377→                </div>
378→                <SheetTitle className="text-lg leading-snug">{selected.title}</SheetTitle>
379→                <p className="text-sm text-muted-foreground">{selected.description}</p>
380→              </SheetHeader>
381→
382→              <Separator />
383→
384→              {/* Details Grid */}
385→              <div className="py-5 space-y-4">
386→                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Details</p>
387→                <div className="grid grid-cols-2 gap-3">
388→                  <div className="rounded-lg border p-3">
389→                    <p className="text-[11px] text-muted-foreground">Votes</p>
390→                    <p className="text-lg font-bold">{selected.votes}</p>
391→                  </div>
392→                  <div className="rounded-lg border p-3">
393→                    <p className="text-[11px] text-muted-foreground">Status</p>
394→                    <p className="text-sm font-semibold">{getStatusStyle(selected.status).label}</p>
395→                  </div>
396→                  <div className="rounded-lg border p-3">
397→                    <p className="text-[11px] text-muted-foreground">Category</p>
398→                    <p className="text-sm font-semibold">{selected.category}</p>
399→                  </div>
400→                  <div className="rounded-lg border p-3">
401→                    <p className="text-[11px] text-muted-foreground">Submitted</p>
402→                    <p className="text-sm font-semibold">
403→                      {new Date(selected.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
404→                    </p>
405→                  </div>
406→                </div>
407→              </div>
408→
409→              <Separator />
410→
411→              {/* Activity */}
412→              {selected.admin_note && (
413→                <div className="py-5 space-y-3">
414→                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Activity</p>
415→                  <div className="flex items-start gap-3">
416→                    <div className="w-2 h-2 rounded-full bg-primary mt-1.5 shrink-0" />
417→                    <div>
418→                      <p className="text-sm">{selected.admin_note}</p>
419→                    </div>
420→                  </div>
421→                </div>
422→              )}
423→
424→              {/* Bottom Actions */}
425→              <div className="border-t pt-4 mt-4 flex items-center gap-2">
426→                <Button
427→                  variant={hasVoted(selected.id) ? "default" : "outline"}
428→                  className="flex-1 gap-2"
429→                  onClick={() => handleVote(selected.id)}
430→                >
431→                  <ChevronUp className="h-4 w-4" />
432→                  {hasVoted(selected.id) ? "Voted" : "Upvote"} · {selected.votes}
433→                </Button>
434→                <Button variant="outline" size="icon" onClick={() => handleShare(selected)} title="Share">
435→                  <Share2 className="h-4 w-4" />
436→                </Button>
437→              </div>
438→            </>
439→          )}
440→        </SheetContent>
441→      </Sheet>
442→    </SidebarLayout>
443→  );
444→};
445→
446→export default RequestFeature;
